import { expect, test, uniqueName } from "../../fixtures";

test("the vendor with an unreadable expiry date is listed above the other", { tag: "@UI-09" }, async ({ pages, signIn, factory }) => {
  // Arrange
  const unreadable = await factory.vendorInReview({
    name: uniqueName("Unreadable Expiry"),
    files: { insurance_certificate: "insurance_certificate_unparseable.txt" },
  });
  const readable = await factory.vendorInReview({ name: uniqueName("Readable Expiry") });
  await signIn("reviewer");

  // Act
  await pages.reviewQueue.goto();

  // Assert
  const unreadableCard = pages.reviewQueue.card(unreadable.vendor.name);
  const readableCard = pages.reviewQueue.card(readable.vendor.name);
  await expect(unreadableCard).toBeVisible();
  await expect(readableCard).toBeVisible();
  const unreadableY = (await unreadableCard.boundingBox())?.y;
  const readableY = (await readableCard.boundingBox())?.y;
  expect(unreadableY ?? Number.POSITIVE_INFINITY, "unreadable card is above the other").toBeLessThan(
    readableY ?? Number.NEGATIVE_INFINITY,
  );
});
